```json
{
  "rationale": "To predict purchases in the next 7 days for H&M, we need to derive features that capture the customer's recent activity and preferences. We will focus on the customer's purchase history within the past 30 days, as well as their interaction with specific product categories.",
  "aggregates": [
    {
      "name": "f_purchase_frequency",
      "keys": ["customer_id"],
      "sql": "count(*)"
    },
    {
      "name": "f_purchase_value",
      "keys": ["customer_id"],
      "sql": "sum(price)"
    },
    {
      "name": "f_average_purchase_price",
      "keys": ["customer_id"],
      "sql": "avg(price)"
    },
    {
      "name": "f_product_diversity",
      "keys": ["customer_id"],
      "sql": "approx_count_distinct(product_code)"
    },
    {
      "name": "f_product_type_diversity",
      "keys": ["customer_id"],
      "sql": "approx_count_distinct(product_type_no)"
    },
    {
      "name": "f_latest_purchase_days_ago",
      "keys": ["customer_id"],
      "sql": "min(days_ago)"
    },
    {
      "name": "f_frequency_product_type_1",
      "keys": ["customer_id", "product_type_no"],
      "sql": "count(*)"
    },
    {
      "name": "f_frequency_product_type_2",
      "keys": ["customer_id", "product_type_no"],
      "sql": "sum(price)"
    }
  ],
  "derived": [
    {
      "name": "f_recent_activity",
      "sql": "f_purchase_frequency * (1 / (f_latest_purchase_days_ago + 1))"
    },
    {
      "name": "f_product_type_affinity",
      "sql": "f_frequency_product_type_2 / f_purchase_value"
    },
    {
      "name": "f_impulse_purchaser",
      "sql": "f_purchase_value / f_product_diversity"
    },
    {
      "name": "f_future_purchase_prob",
      "sql": "f_recent_activity * f_product_type_affinity * f_impulse_purchaser"
    }
  ]
}
```

