{
  "rationale": "Rank articles based on customer purchase history and demographic factors to predict future purchases.",
  "aggregates": [
    {
      "name": "f_customer_purchase_frequency",
      "keys": ["customer_id"],
      "sql": "approx_count_distinct(product_code)"
    },
    {
      "name": "f_customer_discount_frequency",
      "keys": ["customer_id"],
      "sql": "sum(price)"
    },
    {
      "name": "f_customer_discount_average",
      "keys": ["customer_id"],
      "sql": "avg(price)"
    },
    {
      "name": "f_customer_age_group",
      "keys": ["customer_id"],
      "sql": "mode(customer_age) ORDER BY customer_age"
    },
    {
      "name": "f_customer_department_purchase_frequency",
      "keys": ["customer_id", "department_no"],
      "sql": "approx_count_distinct(product_code)"
    },
    {
      "name": "f_customer_product_type_purchase_frequency",
      "keys": ["customer_id", "product_type_no"],
      "sql": "approx_count_distinct(product_code)"
    }
  ],
  "derived": [
    {
      "name": "f_age_group_purchase_rate",
      "sql": "f_customer_purchase_frequency / f_customer_age_group"
    },
    {
      "name": "f_discount_frequency_per_purchase",
      "sql": "f_customer_discount_frequency / f_customer_purchase_frequency"
    },
    {
      "name": "f_discount_value_per_purchase",
      "sql": "f_customer_discount_average * f_customer_purchase_frequency"
    },
    {
      "name": "f_department_purchase_rate",
      "sql": "f_customer_department_purchase_frequency / f_customer_purchase_frequency"
    }
  ]
}
