```json
{
  "rationale": "This program aims to improve the recommendation accuracy by incorporating various customer and product attributes, as well as aggregated features to capture customer behavior and product popularity.",
  "aggregates": [
    {
      "name": "f_customer_purchase_count",
      "keys": ["customer_id"],
      "sql": "COUNT(*)"
    },
    {
      "name": "f_customer_unique_products_bought",
      "keys": ["customer_id"],
      "sql": "COUNT(DISTINCT product_code)"
    },
    {
      "name": "f_product_popularity",
      "keys": ["product_code"],
      "sql": "COUNT(*)"
    },
    {
      "name": "f_product_repurchase_rate",
      "keys": ["product_code"],
      "sql": "SUM(CASE WHEN days_ago < 7 THEN 1 ELSE 0 END) / COUNT(*)"
    },
    {
      "name": "f_customer_recent_purchase",
      "keys": ["customer_id"],
      "sql": "MIN(days_ago)"
    },
    {
      "name": "f_customer_age_group",
      "keys": ["customer_id"],
      "sql": "CASE WHEN raw_u_age < 20 THEN 'young' WHEN raw_u_age >= 20 AND raw_u_age < 40 THEN 'middle' ELSE 'old' END"
    },
    {
      "name": "f_product_type_popularity",
      "keys": ["product_type_no"],
      "sql": "COUNT(*)"
    },
    {
      "name": "f_department_popularity",
      "keys": ["department_no"],
      "sql": "COUNT(*)"
    },
    {
      "name": "f_sales_channel_popularity",
      "keys": ["sales_channel_id"],
      "sql": "COUNT(*)"
    },
    {
      "name": "f_product_colour_popularity",
      "keys": ["colour_group_code"],
      "sql": "COUNT(*)"
    }
  ],
  "derived": [
    {
      "name": "f_customer_average_days_between_purchases",
      "sql": "NULLIF(SUM(days_ago), 0) / f_customer_purchase_count"
    },
    {
      "name": "f_customer_recent_purchase_age",
      "sql": "CASE WHEN f_customer_recent_purchase = 0 THEN raw_u_age ELSE raw_u_age - f_customer_recent_purchase END"
    },
    {
      "name": "f_customer_is_active",
      "sql": "CASE WHEN raw_u_active = 1 THEN 1 ELSE 0 END"
    },
    {
      "name": "f_product_recent_sale",
      "sql": "MIN(days_ago)"
    }
  ]
}
```

