      "name": "f_customer_age_group",
      "keys": ["customer_id"],
      "sql": "mode(case when raw_u_age < 20 then '10-19' when raw_u_age < 30 then '20-29' when raw_u_age < 40 then '30-39' when raw_u_age < 50 then '40-49' else '50+' end)"
